import { useMemo, useState } from 'react';
import {
  Badge,
  Button,
  Card,
  Chip,
  EmptyState,
  Pagination,
  ProgressCircle,
  Stack,
  Text,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over' | 'done';

interface Project {
  id: string;
  name: string;
  spent: number;
  quota: number;
  status: ProjectStatus;
}

interface SpendPanelProps {
  projects?: Project[];
}

const PER_PAGE = 5;

const STATUS_LABELS: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  over: 'Превышена квота',
  done: 'Завершён',
};

const STATUS_TONES: Record<ProjectStatus, 'info' | 'neutral' | 'danger' | 'success'> = {
  active: 'info',
  paused: 'neutral',
  over: 'danger',
  done: 'success',
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'over', 'done'];

const DEFAULT_PROJECTS: Project[] = [
  { id: 'p-1', name: 'Атлас · миграция биллинга', spent: 184_000, quota: 200_000, status: 'active' },
  { id: 'p-2', name: 'Поисковый индекс v3', spent: 96_500, quota: 150_000, status: 'active' },
  { id: 'p-3', name: 'Мобильный онбординг', spent: 41_000, quota: 120_000, status: 'paused' },
  { id: 'p-4', name: 'Аналитика оттока', spent: 238_000, quota: 180_000, status: 'over' },
  { id: 'p-5', name: 'Рефакторинг auth-шлюза', spent: 75_000, quota: 90_000, status: 'active' },
  { id: 'p-6', name: 'Витрина отчётов', spent: 132_000, quota: 130_000, status: 'over' },
  { id: 'p-7', name: 'Логирование и трейсинг', spent: 58_000, quota: 100_000, status: 'paused' },
  { id: 'p-8', name: 'Миграция на TS 5', spent: 64_000, quota: 64_000, status: 'done' },
  { id: 'p-9', name: 'Дизайн-система Jinx', spent: 22_000, quota: 80_000, status: 'active' },
  { id: 'p-10', name: 'Импорт из legacy CRM', spent: 111_000, quota: 110_000, status: 'done' },
];

const formatMoney = (value: number) =>
  new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB', maximumFractionDigits: 0 }).format(value);

const usageTone = (percent: number) => {
  if (percent >= 100) return 'danger' as const;
  if (percent >= 80) return 'warning' as const;
  return 'success' as const;
};

export default function ProjectSpendPanel({ projects = DEFAULT_PROJECTS }: SpendPanelProps) {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => (activeStatuses.length === 0 ? projects : projects.filter((p) => activeStatuses.includes(p.status))),
    [projects, activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PER_PAGE));
  const visible = filtered.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  return (
    <Card padding="lg">
      <Stack direction="column" gap="lg">
        <Stack direction="row" align="center" justify="space-between" gap="md" wrap>
          <Text as="h2" size="lg" weight="semibold">
            Расход по проектам
          </Text>
          <Text size="sm" tone="muted">
            {filtered.length} из {projects.length}
          </Text>
        </Stack>

        <Stack direction="row" gap="sm" wrap role="group" aria-label="Фильтры по статусу">
          {STATUS_ORDER.map((status) => {
            const selected = activeStatuses.includes(status);
            return (
              <Chip
                key={status}
                selected={selected}
                aria-pressed={selected}
                onClick={() => toggleStatus(status)}
                onDismiss={selected ? () => toggleStatus(status) : undefined}
                dismissLabel={`Снять фильтр «${STATUS_LABELS[status]}»`}
              >
                {STATUS_LABELS[status]}
              </Chip>
            );
          })}
        </Stack>

        {visible.length === 0 ? (
          <EmptyState
            title="Ничего не найдено"
            description="Под выбранные статусы не попал ни один проект."
            action={
              <Button variant="secondary" onClick={resetFilters}>
                Сбросить фильтры
              </Button>
            }
          />
        ) : (
          <Stack direction="column" gap="sm" as="ul" aria-label="Проекты">
            {visible.map((project) => {
              const percent = Math.round((project.spent / project.quota) * 100);
              return (
                <Card key={project.id} as="li" variant="outlined" padding="md">
                  <Stack direction="row" align="center" justify="space-between" gap="md" wrap>
                    <Stack direction="row" align="center" gap="md" style={{ minWidth: 'var(--jx-size-64)' }}>
                      <ProgressCircle
                        value={Math.min(percent, 100)}
                        size="sm"
                        tone={usageTone(percent)}
                        aria-label={`Квота израсходована на ${percent} процентов`}
                      >
                        {percent}%
                      </ProgressCircle>
                      <Stack direction="column" gap="xs">
                        <Text weight="medium">{project.name}</Text>
                        <Text size="sm" tone="muted">
                          {formatMoney(project.spent)} из {formatMoney(project.quota)}
                        </Text>
                      </Stack>
                    </Stack>
                    <Badge tone={STATUS_TONES[project.status]}>{STATUS_LABELS[project.status]}</Badge>
                  </Stack>
                </Card>
              );
            })}
          </Stack>
        )}

        {visible.length > 0 && pageCount > 1 && (
          <Stack direction="row" justify="center">
            <Pagination page={page} pageCount={pageCount} onPageChange={setPage} />
          </Stack>
        )}
      </Stack>
    </Card>
  );
}

